extractor:
function extract(raw, memory) {
  var KNOWN = { playing: 1, head: 1, body: 1, coin: 1, heading: 1, turn: 1, edge: 1, score: 1, headOnScreen: 1, screen: 1 };
  var GOOD = /coin|food|apple|fruit|pellet|pickup|bonus|gem|reward/i;
  var DECOR = /cloud|star|decor|particle|score|text|label|background|hud|camera|offset|scale|angle|rotation|velocity|speed|direction|heading|turn|screen|best|time/i;
  function isCell(v) { return Array.isArray(v) && v.length >= 2 && typeof v[0] === 'number' && typeof v[1] === 'number'; }
  function cellsOf(v, depth, out) {
    if (isCell(v)) out.push([Math.round(v[0]), Math.round(v[1])]);
    else if (v && typeof v === 'object' && !Array.isArray(v) && typeof v.x === 'number' && typeof v.y === 'number') out.push([Math.round(v.x), Math.round(v.y)]);
    else if (Array.isArray(v) && depth < 2) { for (var j = 0; j < v.length; j++) cellsOf(v[j], depth + 1, out); }
    return out;
  }
  if (!raw || !raw.playing || !isCell(raw.head)) {
    memory.wait = (memory.wait || 0) + 1;
    return { playing: false, screen: String((raw && raw.screen) || 'End'), waitTicks: memory.wait - 1, score: raw && typeof raw.score === 'number' ? raw.score : (memory.score || 0) };
  }
  memory.wait = 0;
  var score = typeof raw.score === 'number' ? raw.score : 0;
  memory.score = score;
  var E = typeof raw.edge === 'number' && raw.edge > 0 ? Math.round(raw.edge) : 8;
  var N = 2 * E + 1, NN = N * N, i;
  function inB(x, y) { return x >= -E && x <= E && y >= -E && y <= E; }
  function idx(x, y) { return (x + E) + (y + E) * N; }
  var hx = Math.round(raw.head[0]), hy = Math.round(raw.head[1]);
  var body = cellsOf(raw.body, 0, []);
  var coins = cellsOf(raw.coin, 0, []);
  var base = [];
  for (i = 0; i < NN; i++) base.push(0);
  var unkCount = 0, unkKind = '', unkDx = 0, unkDy = 0, unkBest = 1e9;
  for (var key in raw) {
    if (KNOWN[key] || DECOR.test(key)) continue;
    var cs = cellsOf(raw[key], 0, []);
    if (!cs.length) continue;
    if (GOOD.test(key)) { coins = coins.concat(cs); continue; }
    for (i = 0; i < cs.length; i++) {
      var ux = cs[i][0], uy = cs[i][1];
      if (inB(ux, uy)) base[idx(ux, uy)] = 1e9;
      unkCount++;
      var ud = Math.abs(ux - hx) + Math.abs(uy - hy);
      if (ud < unkBest) { unkBest = ud; unkKind = key; unkDx = ux - hx; unkDy = uy - hy; }
    }
  }
  var coinAt = {}, cdx = 0, cdy = 0, cbest = 1e9;
  for (i = 0; i < coins.length; i++) {
    var c = coins[i];
    if (inB(c[0], c[1])) coinAt[idx(c[0], c[1])] = 1;
    var cd = Math.abs(c[0] - hx) + Math.abs(c[1] - hy);
    if (cd < cbest) { cbest = cd; cdx = c[0] - hx; cdy = c[1] - hy; }
  }
  var occ = {};
  for (i = 0; i < body.length; i++) if (inB(body[i][0], body[i][1])) occ[idx(body[i][0], body[i][1])] = 1;
  var OPP = { up: 'down', down: 'up', left: 'right', right: 'left' };
  var heading = OPP[raw.heading] ? raw.heading : null;
  if (!heading && body.length) {
    var hdx = hx - body[0][0], hdy = hy - body[0][1];
    heading = hdx > 0 ? 'right' : hdx < 0 ? 'left' : hdy > 0 ? 'down' : 'up';
  }
  if (!heading) heading = 'up';
  var len = body.length + 1;
  var state = { playing: true, score: score, length: len, heading: heading, coinDx: cdx, coinDy: cdy };
  var DIRS = [['up', 0, -1], ['down', 0, 1], ['left', -1, 0], ['right', 1, 0]];
  for (var d = 0; d < 4; d++) {
    var name = DIRS[d][0], nx = hx + DIRS[d][1], ny = hy + DIRS[d][2];
    var ok = inB(nx, ny) && name !== OPP[heading] && !occ[idx(nx, ny)] && base[idx(nx, ny)] < 1e9;
    var room = 0, tail = false, coinSteps = -1;
    if (ok) {
      var start = idx(nx, ny), eats = !!coinAt[start];
      var segs = [[hx, hy]].concat(eats ? body : body.slice(0, body.length - 1));
      var k = segs.length, vac = base.slice();
      for (i = 0; i < k; i++) {
        if (!inB(segs[i][0], segs[i][1])) continue;
        var si = idx(segs[i][0], segs[i][1]);
        if (vac[si] < k - i) vac[si] = k - i;
      }
      var dist = [];
      for (i = 0; i < NN; i++) dist.push(-1);
      dist[start] = 0;
      if (eats) coinSteps = 0;
      var q = [start], qh = 0;
      while (qh < q.length) {
        var cur = q[qh++], t = dist[cur];
        var cx = (cur % N) - E, cy = (cur - (cur % N)) / N - E;
        for (var nb = 0; nb < 4; nb++) {
          var ax = cx + DIRS[nb][1], ay = cy + DIRS[nb][2];
          if (!inB(ax, ay)) continue;
          var ni = idx(ax, ay);
          if (dist[ni] >= 0 || vac[ni] > t) continue;
          dist[ni] = t + 1; q.push(ni); room++;
          if (vac[ni] > 0) tail = true;
          if (coinSteps < 0 && coinAt[ni]) coinSteps = t + 1;
        }
      }
    }
    state[name + 'Ok'] = ok;
    state[name + 'Safe'] = ok && (tail || room >= 2 * len);
    state[name + 'Coin'] = coinSteps < 0 ? 99 : Math.min(coinSteps, 98);
    state[name + 'Room'] = room;
  }
  if (unkCount) { state.unknownKind = unkKind; state.unknownCount = unkCount; state.unknownDx = unkDx; state.unknownDy = unkDy; }
  return state;
}

teacher:
function teach(state) {
  var s = state;
  if (!s.playing) {
    var w = (s.waitTicks || 0) % 4;
    return w === 1 ? 'key_up' : (w === 3 ? 'start' : 'wait');
  }
  var dirs = ['up', 'down', 'left', 'right'];
  var anySafe = false, i;
  for (i = 0; i < 4; i++) if (s[dirs[i] + 'Safe']) anySafe = true;
  function better(a, b) {
    var ca = s[a + 'Coin'], cb = s[b + 'Coin'], ra = s[a + 'Room'], rb = s[b + 'Room'];
    if (anySafe) { if (ca !== cb) return ca < cb; if (ra !== rb) return ra > rb; }
    else { if (ra !== rb) return ra > rb; if (ca !== cb) return ca < cb; }
    return a === s.heading;
  }
  var best = null;
  for (i = 0; i < 4; i++) {
    var d = dirs[i];
    if (anySafe ? !s[d + 'Safe'] : !s[d + 'Ok']) continue;
    if (best === null || better(d, best)) best = d;
  }
  if (best === null) best = s.heading || 'up';
  return 'key_' + best;
}
